effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

vec3 gradientAt(float t) {
    t = clamp(t, 0.0, 1.0);
    if (t < 0.3333333) {
        return mix(shadow.rgb, midtone1.rgb, t * 3.0);
    } else if (t < 0.6666667) {
        return mix(midtone1.rgb, midtone2.rgb, (t - 0.3333333) * 3.0);
    }
    return mix(midtone2.rgb, highlight.rgb, (t - 0.6666667) * 3.0);
}

void main() {
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    float a = src.a;
    vec3 straight = src.rgb / max(a, 0.0001);
    float y = dot(straight, LUMA);
    if (reverse) y = 1.0 - y;
    vec3 mapped = gradientAt(y) * a;
    gl_FragColor = vec4(mix(src.rgb, mapped, blend), a);
}
